package com.jinloes.practice;
import java.util.*;
import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: an integer array, then k=<distance>, for example: [3, 1, 2, 6, 4, 5] k=2"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) {runInput(String.join(" ",args).trim());return;} assertThat(Solution.sortNearlySorted(List.of(3,1,2,6,4,5),2)).as("Example 1").containsExactly(1,2,3,4,5,6); assertThat(Solution.sortNearlySorted(List.of(2,1),5)).as("Example 2").containsExactly(1,2); System.out.println("Examples passed: 2"); } private static void runInput(String input) {try{int m=input.lastIndexOf("k="); if(m<0)throw new IllegalArgumentException(); int[] a=parseArray(input.substring(0,m).trim()); int k=Integer.parseInt(input.substring(m+2).trim()); System.out.println(Solution.sortNearlySorted(Arrays.stream(a).boxed().toList(),k));}catch(RuntimeException e){System.out.println("Could not read \""+input+"\". "+USAGE);}} private static int[] parseArray(String text){String s=text.trim();if(!s.startsWith("[")||!s.endsWith("]"))throw new IllegalArgumentException("array");String b=s.substring(1,s.length()-1).trim();if(b.isEmpty())return new int[0];String[] parts=b.split(",");int[] a=new int[parts.length];for(int i=0;i<parts.length;i++)a[i]=Integer.parseInt(parts[i].trim());return a;} }

